using System.Diagnostics.CodeAnalysis;

namespace AIAgent.WebApi.DomainLayer.ViewModel;

/// <summary>
/// Response view model returned by the KnowledgeAgent containing the generated response and metadata.
/// </summary>
[ExcludeFromCodeCoverage]
public class KnowledgeResponseVM
{
    /// <summary>
    /// Gets or sets the original user query.
    /// </summary>
    public string Query { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the response generated by the agent.
    /// </summary>
    public string Response { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the session identifier associated with this conversation.
    /// </summary>
    public string SessionId { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the language model that generated the response.
    /// </summary>
    public string Model { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the UTC timestamp when the response was completed.
    /// </summary>
    public DateTime TimestampUtc { get; set; } = DateTime.UtcNow;
}

